INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Circadia', 'Circadia is a first person perspective adventure game with RPG elements in the battle parts. It features characters voices for some of the game characters. There are 14 main characters: 7 males and 7 females. And only 7 characters will be in the last battle of the game. There are different relations (friends or foes) depending of the answers that the player choices.' FROM games WHERE igdb_id = 166567 ON CONFLICT (game_id, language_code) DO NOTHING;
