INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trick''N Snowboarder', 'With a fresh dusting of new powder on the mountain, lock on your board and head down the slope for an incredible downhill experience. Feel the speed and the icy wind on your face as you carve through killer courses and obstacles. Trick''n Snowboarder is a shred-fest of sheer speed and air-catching tricks. Race across the world on 10 international courses in 4 different modes of play.' FROM games WHERE igdb_id = 44923 ON CONFLICT (game_id, language_code) DO NOTHING;
