INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-seven-games-of-the-soul', 13775, '1999-10-01', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaure.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmm97.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Seven Games of the Soul', 'In this dark adventure game you play as an old black man, Marcellus Faust. In an old theme park, now condemned and abandoned because of numerous disappearances which happened there, you meet Mephistopheles, the Devil himself. Mephistopheles is not your typical red devil; he is instead a charismatic, charming and mysterious man. From there, your quest begins. The Devil asks you to help him: he had a quarrel with God (or the Boss, as he calls him) about whether or not 7 souls who lived here during the 1930 Depression era should be condemned.
