INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hype: The Time Quest', 'Hype: The Time Quest is an adventure video game developed by Ubi Soft Montreal and published by Ubi Soft Entertainment. The game, released in the year 1999 along with Alex Builds His Farm (1999), is based on the medieval castle toy series from Playmobil. The U.S. version of the Game Boy Color version was supposed to be released in June 2000, but was delayed for over a year for some reason. The game revolves around Hype, a 22-year-old knight in the service of King Taskan IV, following a quest through time to return to his own era in order to save the kingdom from the evil black knight Barnak. The game was directed by Alain Tascan and featured thirty-two different voice actors, as well as original music by Robbi Finkel.' FROM games WHERE igdb_id = 43559 ON CONFLICT (game_id, language_code) DO NOTHING;
