INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SupeLlite 1500 Series: Reversi II', 'Reversi (also marketed by Pressman under the trade name Othello) is a board game involving abstract strategy and played by two players on a board with 8 rows and 8 columns and a set of distinct pieces for each side. Pieces typically are disks with a light and a dark face, each side belonging to one player. The player''s goal is to have a majority of their colored pieces showing at the end of the game, turning over as many of their opponent''s pieces as possible.
