INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ozawa-Ken', 'Ozawa-Ken is a typing-based fighting game. As you correctly type displayed characters or words, your character delivers attacks to opponents; mistakes or slow inputs leave you exposed to counterattacks. The game features three distinct modes: one-on-one typing battles, “Electric Chopping Kawara” practice for learning key positions, and the faster-paced “Electric Punching Board” with level progression and symbol inputs.' FROM games WHERE igdb_id = 363765 ON CONFLICT (game_id, language_code) DO NOTHING;
