INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('3-d-ultra-radio-control-racers', 9116, '1999-11-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ugu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scdrcv.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3-D Ultra Radio Control Racers', '3-D Ultra has done it again with Radio Control Racers Traxxas Edition, the intense new update to the hot-selling 3-D Radio Control Racers. Eight new tracks take you to the next level. Two completely new game modes push radio control racing to new heights. And now you can fully customize your vehicle to make your ride look as good as it performs. Put your racer to the test on 16 tracks of insane jumps, twisting turns, and off-the-wall pitfalls. Race on three indoor tracks including the Traxxas Raceway with real Traxxas intensity. Exotic plants, ancient ruins, and lava appear everywhere you go on the Aztec track. From bumper-car action to roller-coaster-style turns, you''ll get your thrills on the 3-D Ultra Thrillride track. The bonus game mode RC Soccer will have you spinning your wheels on the turf for hours on end while bonus Battle Ball puts you in the pit against the odds. Go for the cup with circuit racing or jump into a quick race with no qualifying required.' FROM games WHERE igdb_id = 9116 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 9116 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
