INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sesame-street-elmos-123s', 49934, '1999-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4zcb.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sesame Street: Elmo''s 123s', 'Get ready to come and play and learn in SESAME STREET: Elmo''s 123s for the Game Boy Color. Preschoolers love Elmo it''s a simple fact of life and your kids or siblings will have a fun time here while they learn their numbers. There are four basic math concepts to be enjoyed: addition, subtraction, counting, and number pattern recognition. Elmo is the official welcoming committee to visitors from the Planet Zap, and he needs help counting all the stars so his visiting outerspace pals will turn the Sesame Street lights back on. Four cheerful and challenging games await: "How Many Stars," "Beam That Number," "Adding Countdown," and "Take It Away." In "Stars." you''ll count how many stars that a speeding spaceship has left in its wake; "Beam" has you beam a spotlight over three patterns. Correctly match the patterns to the number in the lower right hand of the screen and watch rockets blast into space. "Countdown" has you flying with your jetpack and solving three addition equations, and "Take It Away" is similar, only learning subtraction is the goal. SESAME STREET: Elmo''s 123s from NewKidCo will keep you entertained while you master your numbers.' FROM games WHERE igdb_id = 49934 ON CONFLICT (game_id, language_code) DO NOTHING;
