INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kaseki-sousei-reborn-ii-monster-digger', 228579, '1999-02-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5vc8.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kaseki Sousei Reborn II: Monster Digger', 'On that day, I set foot on "Hokora", which has long been said not to be entered. According to a strange doctor who lives in the town, a mysterious underground world inhabited by unknown creatures spreads out beyond the hole of "Hokora", and fossils with life are buried in it ...・. Apparently, the guy next door, who is always fighting, went looking for a legendary monster. "Let''s lose! I''m going on an adventure with courage!" At that time, the doctor''s words came to my mind. "Without the power of friendship, you can''t know the world ..." The fossil excavation game is back! Collect the fossil fragments buried in the dungeon and revive the monsters on the Lab''s Reborn Machine. Various monsters can be created depending on the attributes and combinations of fossils. Some monsters evolve when the parameters of a specific character exceed a certain value. Strategicity has increased due to the advantages and disadvantages of the character''s orientation, the compatibility between attributes, and the character''s "friendship parameter". You can exchange monsters with a communication cable, or use a pocket printer to seal monsters.' FROM games WHERE igdb_id = 228579 ON CONFLICT (game_id, language_code) DO NOTHING;
