INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Yoda''s Challenge Activity Center', 'Just as Yoda instructed Luke Skywalker in the ways of the Force, now he can instruct your children in the ways of math, music, reading, and other skills -- well, almost. Instead of the swamps of Dagobah as a setting, your kids can sit comfortably in front of the family computer as they play Star Wars: Yoda''s Challenge Activity Center.
