INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kids-tetris', 202059, '1999-10-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5hvb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sch39b.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kids Tetris', 'Kids Tetris is a variation of the classic Russian puzzle game geared towards children. The main characters of the game are the Minos, the pieces that make up the Tetris board. There are four locations where you can play Tetris: the circus, the fire station, the laboratory, and the haunted house. Each board requires a certain amount of lines to be cleared to win Tetris. Since the game is a variation for children, the blocks start out small and fall down slowly. As the game progresses, the pieces become more complex and they fall down faster. After you win, there are many toys and stage props that you can play with in the activity center. You can also print out coloring pages based on the game and a certificate for each stage you play. The game supports both single player and multiplayer. The game is playable with the on-screen mouse controls or the keyboard.' FROM games WHERE igdb_id = 202059 ON CONFLICT (game_id, language_code) DO NOTHING;
