INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Racers', 'Lego Racers is set in the fictional Legoland universe, the game depicts Rocket Racer, the "greatest racing champion" in Legoland. After becoming bored from beating everyone at racing, he decides to create a racing contest, and finds the best racers in the history of Legoland using a dimensional warp machine created by his friend, Veronica Voltage, a genius scientist and mechanic. The player takes on the hosts and co-racers in an attempt to beat Rocket Racer and become the "Greatest Lego Racer of All Time".' FROM games WHERE igdb_id = 422 ON CONFLICT (game_id, language_code) DO NOTHING;
