INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Army Men: Air Attack', 'The green and tan armies once again battle, this time in the air via the Huey (agile helicopter), Chinook (Double rotor heavyweight lifting helicopter), Super Stallion and Apache. The tan army are not the only enemies. Insects also get in the way. You must protect tanks, trucks, other helicopters, a train and even a UFO.' FROM games WHERE igdb_id = 3417 ON CONFLICT (game_id, language_code) DO NOTHING;
