INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pacapaca Passion', 'Paca Paca Passion is a rhythm game with dancers; however, this is very different then Bust A Move. I thank the closest game that I could compare this to is Beat Mania or Pop’n Music. There is a bar on the far left and right of the screen, a white line moves down this bar, and when you see a colored line on the bar, you press the corresponding button when the white bar moves over it.' FROM games WHERE igdb_id = 139118 ON CONFLICT (game_id, language_code) DO NOTHING;
