INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Age of Empires II: The Age of Kings', 'Take control of a powerful civilization. Lead them through 1000 years of the Middle Ages to riches and greatness. Will you Intimidate the world into following you by using military force? Rule the world with honor and nobility by using commerce and diplomacy? Or Underhandedly seize power through conspiracy, deception and regicide? There are many paths to power, there can only be one ruler!' FROM games WHERE igdb_id = 327 ON CONFLICT (game_id, language_code) DO NOTHING;
