INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Crystal Rainforest', 'The game takes place on the planet Oglo. In the kingdom of Azon, the last remaining rainforest is being cut down by the antagonistic "Cut and Run Gang". The king of Azon ordered the Cut and Run Gang to stop threatening the rainforest, and is shortly shot by a poison dart. The two protagonists must take part in a variety of settings and activities to retrieve the magical rainforest crystals to save the king and stop the deforestation of the planet.' FROM games WHERE igdb_id = 151716 ON CONFLICT (game_id, language_code) DO NOTHING;
