INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donkey Kong 64', 'K. Rool has kidnapped the Kongs! Can Donkey Kong rescue his friends, reclaim the Golden Bananas and save his homeland from certain doom? Take out some Kremlings with Chunky''s Pineapple Launcher or Lanky''s Trombone. Float through the air using Tiny''s Ponytail Twirl. Even rocket to the sky with Diddy''s Jetbarrel!' FROM games WHERE igdb_id = 1096 ON CONFLICT (game_id, language_code) DO NOTHING;
