INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Police vs Thief: Violent Chasing', 'A game where the player controls a police car and has to catch the thief by running their car into the thief''s car. It is not possible for the player''s car to go backwards when driving. The game features no music or sound effects.' FROM games WHERE igdb_id = 326652 ON CONFLICT (game_id, language_code) DO NOTHING;
