INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nomiss', 'Nomiss was an online Nintendo-published Adobe Shockwave game made to promote the release of Mario Party 2 on the Nintendo 64. It was playable from the official Mario Party 2 website. The game shows what looks to be a flying saucer with 5 circles on top, reminiscent of the style of the Space Land board from Mario Party 2. The circles are colored orange, green, blue, yellow, and pink. These circles also have portraits of Donkey Kong, Luigi, Toad, a Star, and Princess Peach on their respectively-colored circles, and the Nintendo logo in the center.' FROM games WHERE igdb_id = 231598 ON CONFLICT (game_id, language_code) DO NOTHING;
