INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bugs Bunny: Lost in Time', 'The game stars popular cartoon character Bugs Bunny who finds and activates a time machine after taking a wrong turn at Albuquerque. He ends up in Nowhere, home of a sorcerer named Merlin Munroe ("Moyle" to Bugs, or "Merl" but in Bugs accent). Merlin then informs Bugs that he is lost in time and that he must travel through five different eras of time (spanning 21 levels in total) in order to collect clock symbols and golden carrots that will allow him to return to the present.' FROM games WHERE igdb_id = 3053 ON CONFLICT (game_id, language_code) DO NOTHING;
