INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Love Spelling!', 'Building spelling skills becomes fun-and-games as you bop from planet to planet with your hilarious game-show host. An intelligent tracking system automatically adds misspelled words to your own personalized list, to give you extra practice where you need it most. With over 5,000 key words and 50 spelling-pattern word groups I Love Spelling! is based on core curriculum lessons, to match what kids learn in school. Words are divided into spelling lists that teach you the basics so you can apply it to almost any word in the English language.' FROM games WHERE igdb_id = 339135 ON CONFLICT (game_id, language_code) DO NOTHING;
