INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA In the Zone 2000', 'Get set for some serious net time with KONAMI and the NBA! We''re back In The Zone for PlayStation, Nintendo 64 and GameBoy Color with our best season yet! Lead the break from the tip off with features like three-point contest, pinpoint passing and the slam dunk contest. All 29 NBA teams are here, with 300 actual players suiting up. So are you ready to try to sink the 3 with 2 seconds left? Work on your "D"? Venture into the paint? Or are you just going to sit there with that goofy look on your face? Huh? Huh? Huh?' FROM games WHERE igdb_id = 43718 ON CONFLICT (game_id, language_code) DO NOTHING;
