INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Valkyrie Profile', 'Valkyrie Profile is a role-playing video game developed by tri-Ace and published by Enix (now Square Enix) for the PlayStation. It was released on December 22, 1999 in Japan and on August 29, 2000 in North America. An enhanced port of the game was later released for the PlayStation Portable under the name Valkyrie Profile: Lenneth on March 2, 2006 in Japan, July 18, 2006 in North America, and April 27, 2007 in Europe.' FROM games WHERE igdb_id = 3998 ON CONFLICT (game_id, language_code) DO NOTHING;
