INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Sacred Amulet', 'This 1st person adventure game is set in the time of the Aztecs. A nobleman has been murdered, and you''ve been blamed for it, you must run away and save yourself. Is there a connection between his murder and the strange illness affecting the population? The sacred amulet you hold may be the key to it all.' FROM games WHERE igdb_id = 57581 ON CONFLICT (game_id, language_code) DO NOTHING;
