INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate Soccer Manager ''98', 'Ultimate Soccer Manager or USM is a association football management video game serie for MS-DOS, Commodore Amiga and Windows 95, produced by Impressions and distributed by Sierra from 1995 to 1999. The game was a massive hit in Europe (except in Germany, where it was worse received due to some similarities with managers produced by local software houses such as Software 2000 and Ascaron), although it gained little support in Japan.
