INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ClueFinders 5th Grade Adventures: The Secret of the Living Volcano', 'A sudden tsunami has shipwrecked the ClueFinders on a volcanic island and Owen and Leslie have disappeared! Explore and learn the secrets of the island’s castaways to solve the mystery. Build reading & history, geography & maps, math & fractions, science & circuitry, vocabulary, language arts and more on this perilous journey across the island, under the sea and into the volcano! Then, mastermind a brilliant rescue before the volcano blows!' FROM games WHERE igdb_id = 77048 ON CONFLICT (game_id, language_code) DO NOTHING;
