INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gränsland', 'The main character of Gränsland is on the threshold of adulthood: she leaves her family nest and moves to an apartment in an ordinary building. But it is not as simple as it seems at first sight, and the atmosphere there is not at all neighborly: the tenants are always hiding something, and the mysterious doors in their apartments, which nobody seems to see, emit a dim light' FROM games WHERE igdb_id = 201653 ON CONFLICT (game_id, language_code) DO NOTHING;
