INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('10-pin-bowling', 92273, '1999-08-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co91de.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '10-Pin Bowling', 'Congratulations! You now own your very own bowling alley, in the palm of your hand! Imagine going for a 7-10 split, or trying for that perfect game while surrounded by the sights, sounds and nostalgia of the classic American institution, the bowling alley, 10-PIN BOWLING does just that, immersing the player into a virtual bowling experience, anytime, anywhere. No waiting for an alley here. This classic pastime is synthetically recreated with exquisite detail right down to the polished mahogany lanes. So what are you waiting for? Let''s get working on our average before the leagues begin...' FROM games WHERE igdb_id = 92273 ON CONFLICT (game_id, language_code) DO NOTHING;
