INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spyro 2: Ripto''s Rage!', 'Spyro 2: Ripto''s Rage! is the second game in the Spyro the Dragon series. In this game, Spyro is placed in the land of Avalar rather than the Dragon Worlds. Gameplay flows like the original game Spyro the Dragon, with few variations in control and Spyro''s main abilities intact. The only notable difference is the removal of Spyro''s side-rolling ability, previously activated by L1 and R1.' FROM games WHERE igdb_id = 1577 ON CONFLICT (game_id, language_code) DO NOTHING;
