INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Artist: Paint Studio', 'Mario Artist: Paint Studio is a Mario-themed drawing program that includes several Nintendo-related stamp tools. The game is similar to Mario Paint, but with more features. It was one of only two launch titles for the 64DD. Images could be imported from an RCA source using the capture cartridge or a Game Boy Camera. It also came with a unique four-player drawing mode where four players could collaborate to make one drawing together.' FROM games WHERE igdb_id = 73026 ON CONFLICT (game_id, language_code) DO NOTHING;
