INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beatmania IIDX', 'is a music video game developed by Konami''s music video game division, Bemani, released in Japan on February 26, 1999. The objective is to perform songs using a controller with seven keys and a turntable. Its cabinet contains a widescreen monitor, massive speakers, and eight spotlights. Bemani later developed several updated versions of IIDX to increased success. The game retrospectively received a positive reception from video game publications for its gameplay and increased difficulty.' FROM games WHERE igdb_id = 94920 ON CONFLICT (game_id, language_code) DO NOTHING;
