INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sanyo Pachinko Paradise', 'The first installment of the pachinko series lovingly referred to as "PachiPara", Sanyo Pachinko Paradise is the first game in the longest pachinko gambling series made by Irem, the game features a library, 2 pachinko machines and also a story mode in which the player is a young pachinko gambler that wants to become millionaire playing pachinko machines and impress beautiful girls with his pachinko skills.' FROM games WHERE igdb_id = 55926 ON CONFLICT (game_id, language_code) DO NOTHING;
