INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek: Hidden Evil', 'Following the plot of Star Trek: Insurrection, you have been ordered to command Captain Picard''s shuttle to the Ba''ku planet. On Ba''ku you find a peaceful colony who have discovered the fountain of youth. Romulan forces seek to enslave the inhabitants of Ba''ku and it is up to you save the natives. This game features story-driven missions filled with combat, exploration, and intelligence any fan would enjoy.' FROM games WHERE igdb_id = 50392 ON CONFLICT (game_id, language_code) DO NOTHING;
