INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pepsiman', 'Pepsiman is an action video game developed and published by KID for the PlayStation. It was released in Japan in March 1999, and is based on American carbonated soft drink Pepsi''s superhero mascot with the same name, and focuses the player on avoiding obstacles by running, dashing, and jumping, while Pepsiman automatically runs forward through each of the game''s stages.' FROM games WHERE igdb_id = 79500 ON CONFLICT (game_id, language_code) DO NOTHING;
