INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('paris-1313-the-mystery-of-notre-dame-cathedral', 71411, '1999-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2i79.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paris 1313: The Mystery of Notre-Dame Cathedral', 'Paris 1313 is an adventure game, revolving around a mysterious accident at Notre-Dame cathedral in Paris. As you progress through the game, you play as three different characters, each involved in the mystery in different ways. There''s Jacques, a young goldsmith, Pierre, a young horseman who wants to join the King''s Army, and Rosemonde, a dancer. Most of the game is a straightforward point-and-click adventure game, where you talk to people for information and clues, and find items that you use to solve puzzles. There are also a few arcade-like elements, such as climbing up a chimney and target practice with a bow and arrow. The game progresses in a series of chapters. In each chapter, you must perform a certain task with at least two characters in order to proceed. 
