INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Rock Raiders', 'Lego Rock Raiders is a video game based on the Lego theme of the same name. The game opens with optional training missions and one actual mission unlocked. Most missions require the player to collect a certain amount of Energy Crystals. Some missions require the player to locate Rock Raiders that have been trapped in landslides, or to find certain pieces of equipment and bring it back to their base.' FROM games WHERE igdb_id = 2157 ON CONFLICT (game_id, language_code) DO NOTHING;
