INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neopets Browser', 'Neopets (originally stylized NeoPets, and currently neopets) is a virtual pet website. Users can own virtual pets ("Neopets"), and buy virtual items for them using one of two virtual currencies. One currency, called Neopoints, can be earned within the site, and the other, Neocash, can either be purchased with real-world money, or won by chance in-game.' FROM games WHERE igdb_id = 131370 ON CONFLICT (game_id, language_code) DO NOTHING;
