INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'James Bond 007: Tomorrow Never Dies', 'In 007: Tomorrow Never Dies, which is based on the movie of the same name, the player takes the role of the famous James Bond who fights against Elliot Carver. Carver tries to increase his TV ratings by creating a war between the British and the Chinese. To achieve his goal he sunk a British ship with his stealth ship and made it look like the Chinese Air Force was the offender. Now it is Bond''s responsibility to set things right...' FROM games WHERE igdb_id = 1640 ON CONFLICT (game_id, language_code) DO NOTHING;
