INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ore no Shikabane wo Koete Yuke', 'Ore no Shikabane wo Koete Yuke (roughly, "over my dead body,") is a dungeon crawler RPG where the player controls a clan of warriors, cursed to die young, over several generations as they try to defeat the demon that cursed them. Aside from combat, the player must also manage the clans resources, and ensure a new generation is ready to take over when the curse kills their parents. Set in ancient Japan, the game is heavily influenced by traditional Japanese art and mythology.' FROM games WHERE igdb_id = 65905 ON CONFLICT (game_id, language_code) DO NOTHING;
