INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LaserAge', 'LaserAge is a retro game similar to Galaxian and Galaga clones. This shooter features power-ups and is highly detailed, combining nostalgia with 24-bit colour. Four levels have 100 waves of ships. Destroy 15 enemies with 13 power-ups. Your ship can be controlled with the mouse, which comes in handy when you''re trying to dodge enemy fire. The Gold version features a new interface and a massive list of bug fixes.' FROM games WHERE igdb_id = 342590 ON CONFLICT (game_id, language_code) DO NOTHING;
