INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Catz', 'Catz is a pet simulation game that lets owners name, train and play with adorable kittens. Players adopt a customized kitten from one of thirteen different breeds. Gamers will earn their kitten''s love and loyalty by remembering to feed, groom or play with it. Toys and accessories can be purchased for the kitten from the in-game store. Kittens can communicate with their owners through a variety realistic sounds effects including purring and different types of meows.' FROM games WHERE igdb_id = 16616 ON CONFLICT (game_id, language_code) DO NOTHING;
