INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('3d-hunting-shark', 205947, '1999-03-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6k5a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmq8e.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3D Hunting: Shark', 'Take to the waters on an adventure so real you''ll swear to never turn back. Chart your course through stunning underwater 3D environments on your expedition in search of the prized shark. Locations, weapons, equipment and prey so lifelike you''ll be lucky to get out alive. But if you''re one of the lucky few, you''ll reach the shores with a trophy from a successful expedition--and a chance to once again face off against the trophy of the deep.* Navigate through four 3D waterscapes with lifelike scenery, sounds and equipment. * Choose from four weapons in each environment. * True-to-life prey--kill or be killed! * Real-life scuba gear--monitor your air pressure and decompression to survive. * Supplemental equipment--bait, cage and search light.' FROM games WHERE igdb_id = 205947 ON CONFLICT (game_id, language_code) DO NOTHING;
