INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Princess: Marl Oukoku no Ningyou Hime 2', 'Rhapsody II: Ballad of the Little Princess is a role-playing video game developed and published by Nippon Ichi Software for the original PlayStation and is the second installment in the Rhapsody series. The game takes place twelve years after the event of its predecessor, Rhapsody: A Musical Adventure, and features much of the same characters. Like its predecessor, Little Princess includes many musical interludes and focuses on the themes of falling in love and fulfilling your dreams, though the tactical role-playing game battle system of Rhapsody was discarded for a more traditional RPG battle system.' FROM games WHERE igdb_id = 43903 ON CONFLICT (game_id, language_code) DO NOTHING;
