INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Kingdom of Syree III: The Depths of Hell', 'The third chapter in The Kingdom of Syree saga, The Depths of Hell continues the adventures of the Lord Champion of Syree. With the order in the realm reestablished after the new Keeper of Power is found in Black Magic, the brave hero decides to travel around and see the world. However this journey is soon interrupted by a messenger from King Telbor who demands the Lord Champion''s immediate return to Syree, for a new threat has risen: hellish demons are invading the land of Sheol, and the gateway from which they come must be sealed to stop them.' FROM games WHERE igdb_id = 231537 ON CONFLICT (game_id, language_code) DO NOTHING;
