INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('disneys-beauty-and-the-beast-a-board-game-adventure', 65583, '1999-10-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1w2a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7ic4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Beauty and the Beast: A Board Game Adventure', 'Disney''s Beauty and the Beast: A Board Game Adventure is a game for the Game Boy Color. There are two modes of play. In the first you play on a big game board, where each square represents a Disney character. When you land on a square you play a mini-game against or inspired by him or her. For instance if you land on the square showing the inventor father you will have to play a game where his new log chopping device cuts firewood and he has to bounce it across the screen on a spring. These mini-games range from 2D platform game segments to memory or reflex games. There are a total of seven boards to play on. You can play with up to four players.' FROM games WHERE igdb_id = 65583 ON CONFLICT (game_id, language_code) DO NOTHING;
