INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Madden NFL 2000', 'Madden NFL 2000 is a football video game. The Green Bay Packers had the best team overall in the game with a score of 94. The worst team in the game was the Cleveland Browns with a score of 68. The best offense in the game belongs to the Denver Broncos with a score of 97. The best defense in the game belongs to the Miami Dolphins with a score of 96. The best special teams in the game belongs to both the Buffalo Bills and Atlanta Falcons with a score of 97.' FROM games WHERE igdb_id = 3537 ON CONFLICT (game_id, language_code) DO NOTHING;
