INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Weltorv Estleia', 'Weltorv Estleia is a non-linear role-playing game set in a medieval fantasy world with its own mythical history and lore. The background story involves a battle between seven legendary warriors, led by the young magician Ten, against an evil dragon. The player assumes the role of a nameless adventurer, male or female, who ventures to the city of Farbell. There, he or she is instructed to join the the Adventurers Guild, and eventually becomes involved in the grand struggle against dark forces threatening Estleia.' FROM games WHERE igdb_id = 166556 ON CONFLICT (game_id, language_code) DO NOTHING;
