INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'In-Fisherman Bass Hunter 64', 'Go fishing in the great outdoors with Bass Hunter 64! Reel in a record-setting bass in tournament mode in 3D rendered environments, complete with native wildlife, and geographically accurate landscapes. Fish Pennsylvania''s Lake Arthur and Florida''s Butler Chain Lakes. Lure, strike, and fish-fighting animations are designed to simulate bass fishing''s most exciting moments.' FROM games WHERE igdb_id = 3419 ON CONFLICT (game_id, language_code) DO NOTHING;
