INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legacy of Kain: Soul Reaver', 'A third-person action-adventure game set after the events of Blood Omen: Legacy of Kain (1996). Kain has established a vampiric empire in the world of Nosgoth, but when his lieutenant and progeny, Raziel, evolves wings before him, Kain casts him down in jealousy. Centuries later, Raziel awakens in a corrupted form and sets out to take revenge against his former brethren.' FROM games WHERE igdb_id = 4122 ON CONFLICT (game_id, language_code) DO NOTHING;
