INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Indiana Jones and the Infernal Machine', '1947. The Nazis have been crushed, the Cold War has begun and Soviet agents are sniffing around the ruins of the fabled Tower of Babel. What are they up to? The CIA wants renowned archaeologist and adventurer Dr. Henry "Indiana" Jones, Jr. to find out. Grab your whip and fedora and join Indy in a globe-spanning race to unearth the mysterious "Infernal Machine."' FROM games WHERE igdb_id = 188 ON CONFLICT (game_id, language_code) DO NOTHING;
