INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wipeout 3', 'The third release of Psygnosis''s seminal anti-grav racing series, and also the first game from the series to remain exclusive to the PlayStation. Set in the "F7200 Anti-Gravity Racing League", players control anti-gravity racing craft to eliminate competitors and complete events across a futuristic urban metropolis.' FROM games WHERE igdb_id = 1540 ON CONFLICT (game_id, language_code) DO NOTHING;
