INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jazz Jackrabbit 2: The Christmas Chronicles', 'They are back! Super-cool rabbit jazz, his crazy little brother, Spaz, and their athletic sister Lori will gang up for Christmas to have a wild and wacky time on your PC. In these Christmas levels of the PC hit Jazz Jackrabbit 2, our favourite rabbits have brand new adventures in cold, snowy landscapes, where there are many evil enemies.' FROM games WHERE igdb_id = 134282 ON CONFLICT (game_id, language_code) DO NOTHING;
