INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gradius IV: Revival', 'Gradius IV is the fourth arcade installment in a series of scrolling shooter video games developed by Konami Computer Entertainment Tokyo. It was preceded by Gradius III, released in 1989, although spinoffs had been released prior to it such as Gradius Gaiden. This title brings a considerable graphical upgrade, particularly with the use of colored lighting. In addition, there have been several additions and removals to the vaulted weapons system; specifically, the edit mode has been removed and an online ranking system was added.' FROM games WHERE igdb_id = 1486 ON CONFLICT (game_id, language_code) DO NOTHING;
