INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nhl-2000', 813, '1999-08-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co629f.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NHL 2000', 'You can choose from all of the NHL teams, including the expansion Atlanta Thrashers. Play an Exhibition game to work on your tactics and strategies, and when you are ready for long-term competition, try to endure an 82-game Season, or just skip straight to the Playoffs. While in the game, you will have to learn when to make line changes and determine when it''s a good time to pull the goalie. In addition to these tactical decisions, you must also deal with penalties and infractions including offsides, two-line passes, and icing. However, you can customize the game by turning off certain rules and setting the referee''s strictness. In addition, there are three different difficulty levels. Will you be able to claim the Stanley Cup? The only way to find out is by playing NHL 2000.' FROM games WHERE igdb_id = 813 ON CONFLICT (game_id, language_code) DO NOTHING;
