INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yakouchuu II: Satsujin Kouro', 'Yakouchuu II: Satsujin Kouro is an adventure game for the Nintendo 64 released only in Japan in 1999. Sequel to the Super Famicom game Yakouchuu, released in 1995. Yakouchuu GB was also released in 1999 for the Game Boy Color.' FROM games WHERE igdb_id = 64868 ON CONFLICT (game_id, language_code) DO NOTHING;
