INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dino Crisis', 'Dino Crisis is a survival horror video game developed and published by Capcom in 1999. Set in a remote research facility, it follows special agent Regina as she investigates a scientific experiment gone wrong. The game combines exploration, puzzle-solving, and combat against hostile dinosaurs. It uses a real-time 3D environment rather than pre-rendered backgrounds, distinguishing it from earlier Capcom horror titles. Dino Crisis is often noted for its emphasis on tension, limited resources, and fast, unpredictable enemies.' FROM games WHERE igdb_id = 3027 ON CONFLICT (game_id, language_code) DO NOTHING;
