INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deluxe Ski Jump', 'Deluxe Ski Jump is a shareware ski jumping simulation with full 3D graphics and simulated physics. The game contains 16 different hills, which vary in size from the tiny K50 in England to the huge K250 in Slovenia. DSJ also allows for up to 16 players (computer or human controlled) to compete for the World Cup trophy simultaneously, using the same computer.
