INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rayman 60 Levels', 'Rayman 60 Levels is the third and final collection of levels that expand upon the original Rayman game. It was originally released in 1999 in the pack Rayman Collector, and was later released in Rayman 100 Levels, Rayman Compilation, and as a standalone title in Germany (as Rayman Forever) alongside the Making of Rayman 2 and three mini-games.' FROM games WHERE igdb_id = 193336 ON CONFLICT (game_id, language_code) DO NOTHING;
