INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BFRIS Zero Gravity Fighter Combat', 'First-person 3D accelerated space fighter combat game, played in enclosed arenas connected by teleports. Real physics down to friction, momentum, and inertia. Six vehicles, 11 weapons/powerups, force feedback, 3-D sound. Network play supports 63 players on a LAN and 24 on 28.8 modems. Release version ships shrinkwrapped with Linux & Windows binaries.' FROM games WHERE igdb_id = 85985 ON CONFLICT (game_id, language_code) DO NOTHING;
