INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hugo: Jungle Island 1', 'The friendly troll Hugo''s arch-enemy, the evil witch Scylla, has moved to a jungle island, where she teamed up with the local tyrant Don Croco. Scylla then once again kidnapped Hugo''s wife Hugolina and the children, but this time she keeps them captive in a cage in her new lair, located at a top of volcano in the center of the island. Control Hugo, aided by the monkey Jean Paul and the toucan Ferdinand, as you need to complete a series of minigames to reach and defeat the witch and free Hugo''s family.' FROM games WHERE igdb_id = 264466 ON CONFLICT (game_id, language_code) DO NOTHING;
