INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bird Hunter: Upland Edition', 'Your computer will be your favorite upland destination with this extraordinary 3-D challenge. You''ll hunt the finest locations, select from the choicest weapons, and command the best hunting dogs. It features authentic ammunition and ballistics data from Federal Cartridge and an environment alive with the sights and sounds of the great outdoors.' FROM games WHERE igdb_id = 46952 ON CONFLICT (game_id, language_code) DO NOTHING;
