INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lunar-silver-star-story-complete-collectors-edition', 44960, '1999-06-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/anuynw7ee6czop9hrsp7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/kcv64dsnaydzk9ut3xty.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lunar: Silver Star Story Complete - Collector''s Edition', 'Return to the world of LUNAR, in the completely reworked 32-bit version of the RPG classic. Journey back to a place where dragons yet live, and magic is valued above all else. Join Alex, the young adventurer, as he begins a quest with his friends to save their land from the crushing advance of the Magic Emperor. Explore Dungeons, fight terrifying monsters, and gather information from the locals as you advance toward the explosive encounter with the Magic Emperor himself! Exciting, menu-driven combat will keep you challanged until the last. And, thanks to the storage power of CD and the PlayStation''s built-in movie player, LUNAR contains nearly an hour of incredible animation sequences that will get you involved in the story faster than you ever thought possible. Get ready for the ride of your life...' FROM games WHERE igdb_id = 44960 ON CONFLICT (game_id, language_code) DO NOTHING;
