INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BoaBite 3D', 'BoaBite 3D is a variant of Snake, turning the concept into a 3D game and played from a first-person perspective. The player controls a Boa constrictor who wants to eat fruit. The game is played in a closed environment and the snake can be moved in any direction. Four movement keys are used to control the snake and this can be done in the normal control mode (left and right makes the snake turn) or in the elite control mode (named after the spaceship control in the C64 game Elite) where those keys make the snake roll left or right instead of just turning.' FROM games WHERE igdb_id = 126078 ON CONFLICT (game_id, language_code) DO NOTHING;
