INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pocket Bowling', 'Pocket Bowling for the Game Boy Color brings the popular blue collar sport to the tips of your fingers (and thumbs). You can choose from six bowlers, including a secret android character who appears only after you reach a certain level. Each bowler is rated on power and technique and uses a different weight of bowling ball. Apparently, all the bowlers are ambidextrous because each one can bowl right- or left-handed.' FROM games WHERE igdb_id = 96797 ON CONFLICT (game_id, language_code) DO NOTHING;
