INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Fire Spirits', 'This is a clone of the Atari vector game Star Wars, which is comprised of three waves. The player starts with six shield units, which will drop every time a spaceship or any other obstacle collides with the player or the player is hit by enemy fire; if the player is hit when they have no more shields left the game will end.' FROM games WHERE igdb_id = 37538 ON CONFLICT (game_id, language_code) DO NOTHING;
