INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Itacante: La Cité des robots', 'In this adventure and puzzle game made for children, players need to save the citizens of Itacante and fight against the tyrant Vulcor. Helped by their companions, they must construct and use robots to solve various puzzle boards, while being introduced to multiple scientific concepts.' FROM games WHERE igdb_id = 327995 ON CONFLICT (game_id, language_code) DO NOTHING;
