INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CrossTown 2: Ängeln', 'The Angel is the second part of the award-winning CD-ROM trilogy set in Cross Town. As in The Poison, the first part of the trilogy, the action is played out among the citizens of the strange little town of Cross Town, which is - quite literally - a little planet. You will meet the main character, Minna, and several other characters from The Poison. Even though the two are completely independent works, your experience of the game will have an extra dimension if you have ''been'' to Cross Town before.' FROM games WHERE igdb_id = 130005 ON CONFLICT (game_id, language_code) DO NOTHING;
