INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Backyard Football 1999', 'Backyard Football is a football video game released by Humongous Entertainment in 1999. The game was the third Backyard game released by Humongous Entertainment, preceded by Backyard Soccer and Backyard Baseball. It is the first of all of the Backyard Sports series to consist of the Backyard kids and professional players as kids.' FROM games WHERE igdb_id = 50298 ON CONFLICT (game_id, language_code) DO NOTHING;
