INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Wrath of Sona', 'A freeware classic style RPG made in QuickBasic. The game''s plot involves the main character becoming a Mage Knight, though their master is killed as they were about to learn the most powerful spell. Character portraits are photos downloaded from the internet.' FROM games WHERE igdb_id = 275622 ON CONFLICT (game_id, language_code) DO NOTHING;
