INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Intruder', 'The Intruder is an interactive narrative based on a story by Jorge Luis Borges. The viewer must compete in some rudimentary games to hear, read and see the story. Thoroughly well-observed, and compelling, The Intruder takes about 15 minutes to navigate. The games are not difficult but act as an aid to the narrative and introduce levels of addiction to the telling of the story.' FROM games WHERE igdb_id = 174706 ON CONFLICT (game_id, language_code) DO NOTHING;
