INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Christmas Seaman: Omoi o Tsutaeru Mou Hitotsu no Houhou', 'A limited-edition demo version of Seaman titled Christmas Seaman was released in Japan on December 16, 1999, and available for only ten days either through the Sega Direct online store or as part of an exclusive red Dreamcast pack-in. The title allowed players to connect to the online servers and exchange Christmas wishes and messages, while a Santa themed Seaman shares some of his trademark "Seaman wisdom".' FROM games WHERE igdb_id = 283108 ON CONFLICT (game_id, language_code) DO NOTHING;
