INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Supercross 2000', 'EA SPORTS introduces the exclusive game of the Supercross Series. There are 24 riders, 16 real stadiums, 21 real tracks, and 3 freestyle courses bring the Supercross to life. Race for the checkers in a Quick Race then compete for the Championship- or fly with style in freestyle mode. Bar-to-Bar competition, big air, sick tricks, 2-player mode, and real Supercross series make EA SPORTS Supercross 2000 the game to beat!' FROM games WHERE igdb_id = 3610 ON CONFLICT (game_id, language_code) DO NOTHING;
