INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robbit Mon Dieu', 'Robbit Mon Dieu, sometimes referred to as Jumping Flash! 3, is a 3D platform game for the Sony PlayStation. The inhabitants of planet Hananuma find themselves encountering numerous problems that they are unable to solve alone, and their call for help is answered by the Universal City Service, who send Robbit to Hananuma to rectify things and put the inhabitants at peace once again. Robbit now has a slamming move after pressing the triangle button while in the air.' FROM games WHERE igdb_id = 63781 ON CONFLICT (game_id, language_code) DO NOTHING;
