INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Athena: Awakening from the Ordinary Life', 'Athena: Awakening from the Ordinary Life is a 3D RPG game developed by Yumekobo and published by SNK released in March 1999 for the PlayStation. It was released again as a PSOne Classic on PSN for the PlayStation 3 and PSP on August 28, 2007. The game''s image song, "wannabe /Misty Eyes", was performed by RUMI . The game''s story is notorious for being much darker than other Athena related titles.' FROM games WHERE igdb_id = 43832 ON CONFLICT (game_id, language_code) DO NOTHING;
