INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Perry Rhodan: Thoregon - Die verbotene Stadt', 'A new exciting adventure from the Thoregon cycle. Perry Rhodan will find a hostile world, a strange city with bizarre inhabitants. His goal is to escape from there. He has to find a spaceship, whatever the cost. But this is a dangerous endeavor that requires empathy, elbow, intelligence, humor, and cooperativeness. An exciting game with impressive graphics, communication with all living beings and a user-friendly interface.' FROM games WHERE igdb_id = 116601 ON CONFLICT (game_id, language_code) DO NOTHING;
