INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sesame Street: Elmo''s Number Journey', 'Preschoolers are in for a wonderful number-packed good time. Explore magical worlds with Elmo and his Sesame Street friends as he snowboards, jetskis, and drives off on an exciting video game adventure! Helps children ages 3 - 6 with number recognition and basic math skills. Three skill levels easily adjustable by parent or child. Features voices from the beloved TV show.' FROM games WHERE igdb_id = 44031 ON CONFLICT (game_id, language_code) DO NOTHING;
