INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fighter-maker', 4636, '1999-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/em6oshtcd7asnvnm7fld.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scpwho.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fighter Maker', 'Have you ever played a fighting game and thought you could come up with something better? Then it''s time to put your money where your mouth is with FIGHTER MAKER. You can create the character of your dreams, because every aspect can be edited: you can alter wardrobe, hair color, muscle tone, and skin color. Developing poses and artificial intelligence for your characters will bring them to life. For those who like some plot in their fighting games, you can create detailed profiles and histories for every character you create. Once you have a character that looks right, create the moves, combinations, and throws that will allow your fighter to become the greatest. Be sure to give all of your moves damage values, because you want that awesome kick or throw to cause a serious amount of damage. If you don''t like something in FIGHTER MAKER, you can always change it. If you ever thought you could create the ultimate fighting machine, now''s your chance with FIGHTER MAKER.' FROM games WHERE igdb_id = 4636 ON CONFLICT (game_id, language_code) DO NOTHING;
