INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chase Ace 2', 'Fly your spaceship around on the level and shoot at everything that shoots at you. There are refueling zones where ailing ships can replenish their shields and weapons and safe zones that offer a respite from the action, but there''s little time to think about anything other than your immediate survival.' FROM games WHERE igdb_id = 153610 ON CONFLICT (game_id, language_code) DO NOTHING;
