INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Million Hits', '''Million Hits'' contains a whopping 100 songs, widely ranging from J-Pop to Enka! With iconic hits, you can play all your favorite songs. This game also adds the latest hits and popular songs every month, so even the heaviest music nerd can enjoy these songs with ease. Player requests can be added to the game, and the most requested songs at the end of the week and month respectively will be added to the game! You can also jam with another player, alternating or harmonizing for a karaoke-like experience!' FROM games WHERE igdb_id = 266898 ON CONFLICT (game_id, language_code) DO NOTHING;
