INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SNK vs. Capcom Card Fighters'' Clash - Capcom Card Fighter''s Version', 'SNK vs. Capcom: Card Fighters'' Clash, released in 1999 for the Neo Geo Pocket Color handheld console, was the first crossover between SNK and Capcom. Characters in the game are illustrated in the super deformed (chibi) art style. There are two complementary versions of the game: the SNK version and the Capcom version. Each version of the game has a different starting deck and different exclusive cards that can be obtained, but the gameplay remains the same, with card battles resembling a somewhat simplified version of Magic: The Gathering, in which a maximum of three fighters are allowed in each player''s field at any given moment and there is no mana to be spent to place them in the field.' FROM games WHERE igdb_id = 28398 ON CONFLICT (game_id, language_code) DO NOTHING;
