INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SpikeOut: Final Edition', 'Spikeout: Final Edition is the 1999 update for Spikeout: Digital Battle Online, and the second in the Spikeout series of arcade games. It replaces the game''s attract sequence, balances out the characters, adds 2 new stages and bonus stages, and adds a cutscene explaining the backstory of the game''s villain Mikhael.' FROM games WHERE igdb_id = 319157 ON CONFLICT (game_id, language_code) DO NOTHING;
