INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Land Before Time: Preschool Adventure', 'The Land Before Time: Preschool Adventure is an educational game for Windows-based PCs intended for children ages 3-5. It was developed by WayForward Technologies and was originally released by Sound Source Interactive in North America in 1999. Designed for players to "have fun, develop their creativity, and learn about teamwork", the game features activities that contain story construction, musical games, and crafts. The game was re-released in October 2005 by Brighter Child.' FROM games WHERE igdb_id = 329647 ON CONFLICT (game_id, language_code) DO NOTHING;
