INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thrust Twist + Turn', 'Thrust, Twist + Turn is a fast-paced racing game using Twilight 3D''s 3DGE engine. There are eight tracks in total, with a futuristic atmosphere and different themes: Egypt, the city, a hurricane path in the sea, a rush through the clouds... complete with jumps, corkscrews and loops. There are no invisible side edges to the tracks, players can push your opponents into oblivion.
