INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BassMasters 2000', 'BassMasters 2000 is a fishing simulation game which counts a total of 4 modes and has a variety of customizable options. You can create and save up to 7 anglers through the “Create Angler” option, customising characteristics such as sex, hair, face, clothes, etc. Other customisable options include “Lake Conditions” (lake location, season, weather, time, etc.), “Boat” (boat model, engine, etc.) and “Tackle” (rod/reel, line, lure, etc.).' FROM games WHERE igdb_id = 3420 ON CONFLICT (game_id, language_code) DO NOTHING;
