INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deer''s Revenge', 'It''s Hick season--year ''round! Feel the thrill of hunting alongside Ralph Bambillo, the deer with an attitude. Practice aiming with your beer-can gun, net gun, or stun gun at the target range; or choose to hunt the deer in their natural habitats. Then get ready to lock your sights on a big seven-toothed Hick!' FROM games WHERE igdb_id = 112655 ON CONFLICT (game_id, language_code) DO NOTHING;
