INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'G1 Jockey', 'Race to become the leading jockey--vie for the rookie of the year award as an apprentice, gain wins, collect G1 trophies, and earn money on your way to the Triple Crown. Compete with 65 computer jockeys each season, choose from over 2000 unique racehorses to ride, and negotiate with the trainers to ride the top horses each week. The game also includes exciting 2-player head-to-head action, including steeplechase courses.' FROM games WHERE igdb_id = 44695 ON CONFLICT (game_id, language_code) DO NOTHING;
