INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rushdown', 22836, '1999-03-28', 20, 'https://images.igdb.com/igdb/image/upload/t_cover_big/irven5uzja5jhahwsz4s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/bk40k5knjyoioxvu7kzo.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rushdown', 'Travel across the globe to compete in Africa, Europe, America, Asia, and Japan. Choose one of four 3D characters and their equipment for each event. Kayaks, snowboards, and bikes are all individually rated in speed, handling, and grip, so you''ll be able to select a model that suits your playing style before racing. Proud of the way you thrashed the opposition? Records for each course are saved to memory card along with names. Rushdown also features Dual Shock Analog Controller support, instant replays, 13 music tracks from six French bands, and an option to play a friend on either a horizontally or vertically split screen.' FROM games WHERE igdb_id = 22836 ON CONFLICT (game_id, language_code) DO NOTHING;
