INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pandora''s Box', 'In the game, players must travel around the world to different cities solving various kinds of puzzles to capture the seven "tricksters" - Maui, Puck, Eris, Coyote, Monkey, Anansi and Raven. Each trickster has a challenge puzzle after finding all the missing box pieces, acquired by solving the puzzle with each piece behind it in each city. The location of the pieces is randomized each game. The game offers sporadic bonuses. Hints are used to find where one piece goes if the player needs help figuring it out. Free puzzle tokens solve puzzles for the player if needed. A free puzzle token is awarded for every ten puzzles solved.' FROM games WHERE igdb_id = 76200 ON CONFLICT (game_id, language_code) DO NOTHING;
