INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Furby: Big Fun in Furbyland', 'Furby: Big Fun in Furbyland! is an interactive children''s software designed for ages 4-7. Players can create and customize their own Furby characters, explore a virtual clubhouse, and engage in four distinct games. The program offers design features, interactive environments, and skill-based challenges that encourage creativity and problem-solving. With multiple gameplay modes and educational elements, the software provides an entertaining digital experience for young users.' FROM games WHERE igdb_id = 91811 ON CONFLICT (game_id, language_code) DO NOTHING;
