INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Go Kart Challenge', 'Go Kart Challenge is a decent go-kart racing game from Data Becker. The game features a good range of options: three levels of difficulty (Hobby, Amateur, and Pro), three types of drivers (essentially different body weights), 4 original kart models with 8 paint jobs, support for up to 8 players via LAN in single races or tournaments, customizable weather conditions including fog and rain, 4 outdoor tracks, 2 indoor tracks, and 2 zany cartoon tracks. You can even use a versatile track editor to construct your own tracks.' FROM games WHERE igdb_id = 140986 ON CONFLICT (game_id, language_code) DO NOTHING;
