INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Climax Landers: Motte ke! Minige Campaign', 'Retail disc used in a Japan-wide store campaign before Climax Landers/Time Stalkers for Dreamcast was released. It allowed you to download 3 different free Climax Landers related mini games to your VMU, if you brought it to a participating location. Copies of the disc have since been sold online unofficially.' FROM games WHERE igdb_id = 283331 ON CONFLICT (game_id, language_code) DO NOTHING;
