INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kiganjo', 'In order to save a girl who has been kidnapped, the main character, Hayato, challenges the impenetrable castle "Kiganjo". It consists of a variety of stages in which you clear traps unique to period dramas, such as hidden doors and stone drops, and progress while making use of those traps. Battles use a turn-based system where you can attack up to three times in one turn.' FROM games WHERE igdb_id = 300658 ON CONFLICT (game_id, language_code) DO NOTHING;
