INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Racing Lagoon', 'Racing Lagoon is a racing RPG. Your earn experience for your various car parts and racing points by challenging other cars on streets modeled after the actual roadmaps of Yokohama, Japan. After winning a race, you''ll get a certain amount of "Reward Points" which you can then use to take a part from your opponent''s car, anything from the engine to the paint scheme. The game is broken up into 10 nights of racing, with main character Sho Akasaki trying to become the king of the underground racing scene.' FROM games WHERE igdb_id = 76182 ON CONFLICT (game_id, language_code) DO NOTHING;
