INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maisy''s Playhouse', 'In this game the player is introduced to three rooms in Maisy''s house; in each room are many clickable animations to explore with the mouse - drawers and cabinets open to reveal items, water runs and the toilet flushes, toys move and lights click on and off. There are three levels to choose from, and at the 3rd level Maisy will enter the room and perform an appropriate activity, such as taking a bath or donning outdoor clothing. In the top left of each screen is an easel icon which brings the player to a page of seven mini-games.' FROM games WHERE igdb_id = 73961 ON CONFLICT (game_id, language_code) DO NOTHING;
