INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The F.A. Premier League Stars', 'Featuring the most exciting and challenging football league in the world, The F.A. Premier League Stars allows players to experience the fast paced action of the English Premier League right from the start of the 2000/2001 season. Whether it''s the passion of a local derby or the thrills of an end of season championship decider, The F.A. Premier League Stars 2001 offers it all.The F.A. Premier League Stars now features "Stars Challenges" with increased opportunities to win Stars by performing spectacular feats on the pitch, and therefore improve the team. Most exciting of all, the game features a brand new "Stars Stakes" system which will enable the user to play against an opponent whilst wagering their players on the outcome of the game - just imagine losing David Beckham to your Manchester City supporting mate!' FROM games WHERE igdb_id = 43790 ON CONFLICT (game_id, language_code) DO NOTHING;
