INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shanghai: Second Dynasty', 'Shanghai: Second Dynasty includes several modes: Classic Shanghai, Dynasty, Pandamonium, as well as Windstorm and new "beat-the-clock" arcade modes. An official American Mah-Jongg association product, Second Dynasty now includes four authentic versions of Mah-jongg. Fifty-four tilesets are now included, with optional "power tiles" useful for the multiplayer mode. Players can create their own tiles by importing custom images. The game also includes an online mode where players can compete against each other.' FROM games WHERE igdb_id = 71959 ON CONFLICT (game_id, language_code) DO NOTHING;
