INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'O.To.I.Re: Dreamcast Sequencer', 'O.to.i.Re: Dreamcast Sequencer is a Japan-exclusive Sega Dreamcast music creation game by Waka Manufacturing. It was released only in Japan, and allows the player/user to produce his or her own music tracks via the Dreamcast Controller, Dreamcast Microphone, or Dreamcast MIDI Interface Cable. Additionally, this was the only piece of software released in the Dreamcast''s lifespan that supported it''s MIDI adapter cable.' FROM games WHERE igdb_id = 283303 ON CONFLICT (game_id, language_code) DO NOTHING;
