INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro 18: World Tour Golf', 'This golf game has TV-style presentation, with commentary by Peter Alliss and Bobby Clampett. Courses and players are photo-realistic, with course layouts accurate to within 3 centimetres. There are no fly-bys, although you can pan around the course to give some clues as to its layout. Four button presses are used to take a shot; draw and fade are set by how long the appropriate press is held down for.
