INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kita he: White Illumination', 'The player, a second-year high school student (17 years old), travels from Tokyo to Sapporo in Hokkaidō (hence the basic title of the game Kita E - To The North). There, he encounters eight different girls, including the lead character Kotori Haruno, whose family he stays with during his time up north. In the game, the player explores the island, plays video games, does karaoke, goes shopping -- and most of all, tries to find that special someone to share his heart with.' FROM games WHERE igdb_id = 22825 ON CONFLICT (game_id, language_code) DO NOTHING;
