INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Langrisser Millennium', 'Langrisser (ラングリッサーミレニアム) is a tactical role-playing gamesvideo game series created by Masaya. The development team working under Masaya is Career Soft. The Growlanser is considered the spiritual successor to Langrisser. The series maintains a fantasy Germanic setting, but draws on religious concepts like ditheism and sword worship for historical context.' FROM games WHERE igdb_id = 45800 ON CONFLICT (game_id, language_code) DO NOTHING;
