INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Germs: Nerawareta Machi', 'Germs: Nerawareta Machi is a first-person open world adventure game released exclusively in Japan for the PS1. The only game developed and published by Japanese CG animation company KAJ, Germs stars a reporter who returns to his hometown to investigate a mysterious glowing object, as well as a series of mutations happening to the townspeople that might be connected to it.' FROM games WHERE igdb_id = 62438 ON CONFLICT (game_id, language_code) DO NOTHING;
