INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Magic Artist', 'Disney’s Magic Artist Studio lets you draw, paint, and create animations with your favorite Disney characters. Create, animate, and print your images with tools and paints that burst onto your screen. Roses sprout from your canvas, and butterflies soar through 3-D paintings virtually dripping with color. Disney character images dance to disco, rock, classical, and island beats.' FROM games WHERE igdb_id = 46432 ON CONFLICT (game_id, language_code) DO NOTHING;
