INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NHL FaceOff 2000', 'In NHL FACEOFF 2000 you can make trades, release slackers, create a player, and sign free agents. You''ll get gameplay modes like Season, Exhibition, Quick Start. One new feature is Multi-Team play, which lets more than one user play within the same season and creates the potential for some great rivalries. FACEOFF 2000 is officially licensed and has all the real NHL teams and players.' FROM games WHERE igdb_id = 20432 ON CONFLICT (game_id, language_code) DO NOTHING;
