INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('motocross-maniacs-2', 49891, '1999-10-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co81mn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmj1m.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Motocross Maniacs 2', 'The action of motocross comes to the Game Boy Color with MOTOCROSS MANIACS 2. Hop on a motorcycle and hit the bumps, jumps, and loops of each track. Try to earn the fastest time in the Time Trial mode or take on five different tracks in the Championship mode. No matter how you play, there are power-ups scattered throughout the tracks including nitros, mini riders, jets, gasoline, super suspension, speed, and radials. If you don''t like any of the 10 packaged tracks, you can create your own with the Track Editor option. There are a total of 255 obstacles and 32 different items that can be placed on any of the three tracks that you create. Once you have a masterpiece, share it with a friend via a link cable. Get motocross action with MOTOCROSS MANIACS 2.' FROM games WHERE igdb_id = 49891 ON CONFLICT (game_id, language_code) DO NOTHING;
