INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sylvanian Families: Otogi no Kuni no Pendant', 'An ivory rabbit called Aster Dandelion ventures into the heart of the forest during a picnic and aids an injured fairy. She is left with a magical pendant that has a mysterious power that turns reality into dreams at the stroke of six in the evening. Now Aster has a quest to return the pendant to Fairyland while she tries to carry on with her daily life.
