INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rocket-robot-on-wheels', 2644, '1999-10-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa5ns.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1te5.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rocket: Robot on Wheels', 'First-time Nintendo 64 developer Sucker Punch Studios jumped onto the scene with a highly original 3D platformer. The design philosophy behind the title is simple -- rather than build the platformer around the main character, the software house opted instead to focus on the interactivity of the 3D environments he travels. To that end, Rocket employs an advanced physics engine which allows the main character, a lovable unicycle-based robot named Rocket, to travel and experiment with colorful, platform-esque worlds with realistic gravity and inertia. Every object has its own set of lifelike attributes that must be "weighed" into consideration when solving puzzles.' FROM games WHERE igdb_id = 2644 ON CONFLICT (game_id, language_code) DO NOTHING;
