INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Richard Scarry''s Busytown', 'This is an enhanced remake of the 1993 game of the same name, featuring improved graphics, animation and voice acting that is now based on the 1994 to 1997 animated TV series "The Busy World of Richard Scarry". All the activities except for Bananas Gorilla and The Junior Seesaw are faithfully recreated for this Windows and Macintosh release.' FROM games WHERE igdb_id = 132142 ON CONFLICT (game_id, language_code) DO NOTHING;
