INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brave Firefighters: Real Life Heroes', 'Sega arcade game that uses a light-gun controller shaped like a fire hose. The debut title for the Sega Hikaru arcade system in 1999, it had the most technically advanced graphics of its time. It was the first game with Phong shading, the most common shading technique today, and it had the most advanced lighting and particle effects of its time.' FROM games WHERE igdb_id = 68307 ON CONFLICT (game_id, language_code) DO NOTHING;
