INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flight Unlimited III', 'Flight Unlimited III is a 1999 flight simulator that recreates civilian aviation around Seattle, Washington. Players can freely explore or undertake challenge missions in accurately modeled aircraft, supported by real-time weather systems and detailed terrain rendering. Developed by Looking Glass Studios and published by Electronic Arts, the game expanded on its predecessor with enhanced physics and more aircraft options, though its commercial performance was limited with only 20,000 units sold in the US during its release year.' FROM games WHERE igdb_id = 715 ON CONFLICT (game_id, language_code) DO NOTHING;
