INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution 3rdMix', 'Dance Dance Revolution 3rdMix, or 3rdMix, is the 3rd game in the Dance Dance Revolution series of music video games. It was released in the arcades by Konami on October 30, 1999. Although only officially released in Japan, units exist worldwide. It has a total of 68 songs, 35 of which were new to Dance Dance Revolution.
