INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'YSFlight', 'Shoot down waves of hostile aircraft offline, demolish nearly any ground object with any weapon, or challenge other combat pilots online to test your mettle as a flying ace. Use the navigation instruments to plot a peaceful flight, or hunt your prey with air to ground missiles, coming in for the kill with a hail of gunfire. Fly aerobatic formations, fight in ultra-lights, or land a strategic bomber on a helicopter pad. The only limits are your imagination, your add-on collection, and the rules of the server where you fly.' FROM games WHERE igdb_id = 50309 ON CONFLICT (game_id, language_code) DO NOTHING;
