INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NHL FaceOff 99', '989 Studios makes the race for the best hockey title a bit more interesting. Like EA Sports, 989 Studios is building on a previous title to make it better. The game features New Jersey Devil announcer, Mike Emrick and ESPN''s Darren Pang providing play-by-play; graphic and control upgrade; TV-style gameplay; in-depth stat tracking, season play, exhibition games, and more.' FROM games WHERE igdb_id = 20431 ON CONFLICT (game_id, language_code) DO NOTHING;
