INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Civilization: Call to Power', 'Civilization: Call to Power is a turn-based empire building game. The players start a civilization in the stone age and lead them to the future through science, diplomacy, war, trade, and other actions. Eventually, the player will be building colonies in space and cities in the ocean if the player can survive.' FROM games WHERE igdb_id = 9930 ON CONFLICT (game_id, language_code) DO NOTHING;
