INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NASCAR 2000', 'Prove you can handle the thunder! Featuring more drivers - Dale Earnhardt Jr., Tony Stewart and Adam Petty join the field of 33 NASCAR drivers and 7 legends. 18 licensed NASCAR tracks, now including Homestead-Miami Speedway. New TV and Crew Chief audio - Bob Jenkins and Benny Parsons in the booth plus Crew Chief and Spotter assistance. Wheel-to-wheel NASCAR competition - go head-to-head on the split-screen! Six driving views, including behind the wheel. Multiple modes - Quick Race, Single Race, or Championship Season.' FROM games WHERE igdb_id = 3548 ON CONFLICT (game_id, language_code) DO NOTHING;
