INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ted Nugent - Wild Hunting Adventure', 'Experience the thrill of the hunt with Ted Nugent. In this beautifully detailed 3-D hunting simulation, set in Nugent''s Hunting World, Ted helps you bag exotic trophy game. Armed with an array of hunting gear, you stalk the most challenging and dangerous beasts of the wilderness, such as wild boar, grizzly bear, and buffalo. Study their droppings, markings, and scrapes to track them. Then select the right weapon to take them down.' FROM games WHERE igdb_id = 118558 ON CONFLICT (game_id, language_code) DO NOTHING;
