INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('good-night-mr-snoozleberg', 321456, '1999-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co90cg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scudfb.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Good Night Mr. Snoozleberg', 'Expert diplomat Mr. Snoozleberg has a busy schedule: bullet-train inaugurations, movie awards, alien invasions, theme park visits. He can handle everything, though, as long as he gets a good night rest... and his sleepwalking makes that difficult. It''ll be up to you to prevent international incidents by point and clicking objects at the right time to form a safe platforming path!' FROM games WHERE igdb_id = 321456 ON CONFLICT (game_id, language_code) DO NOTHING;
