INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tomb Raider II: Gold', 'Tomb Raider II: Gold is an expanded version of Tomb Raider II, it includes the scenarios of the original game with the addition of five new bonus levels in a separate mini-adventure entitled the "Golden Mask". Unlike the other two expanded games however, this contains no story ties to its corresponding game from the main Tomb Raider series. Its plot is completely unique.' FROM games WHERE igdb_id = 27554 ON CONFLICT (game_id, language_code) DO NOTHING;
