INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 7739 AND p.igdb_id = 6 ON CONFLICT DO NOTHING;
INSERT INTO game_screenshots (game_id, url, display_order, is_featured) SELECT id, 'https://images.igdb.com/igdb/image/upload/t_1080p/tjgidthbmnrcxakm1bcu.jpg', 0, true FROM games WHERE igdb_id = 7739 ON CONFLICT DO NOTHING;
